const app=document.getElementById("app");
const toastEl=document.getElementById("toast");

const navItems=[
  ["dashboard","▦","Dashboard"],["realtime","◉","Real-Time Monitoring"],["charging","▣","EV Charging Control"],
  ["analytics","⌁","Solar Analytics"],["weather","☀","Weather"],["history","◷","Energy History"],
  ["alerts","!","Alerts"],["catalogue","☷","Project Change Catalogue"],["developers","♙","About Developers"],["settings","⚙","Settings"]
];

const state={
  loggedIn:localStorage.getItem("soltech_demo_login")==="1",
  page:"dashboard", mode:"AUTO", monitoring:true, systemPower:true, grid:true,
  charging:"CHARGING", limit:7.4, battery:68, solar:8.6, evPower:6.2, totalEnergy:1248.4,
  todayEnergy:32.8, delivered:18.4
};

const history=[
 ["2026-08-30","34.6","18.4","1.8","82.4%","03:12:18","ONLINE"],
 ["2026-08-29","31.8","16.9","2.1","79.6%","02:54:41","ONLINE"],
 ["2026-08-28","36.2","20.1","1.4","85.1%","03:28:12","ONLINE"],
 ["2026-08-27","29.7","15.3","2.6","76.8%","02:41:33","ONLINE"],
 ["2026-08-26","33.9","17.8","1.9","81.9%","03:05:07","ONLINE"],
 ["2026-08-25","30.4","16.1","2.2","78.3%","02:49:18","ONLINE"],
 ["2026-08-24","35.7","19.5","1.5","84.7%","03:21:05","ONLINE"]
];
const alerts=[
 ["success","Charging Started","EV charging session started successfully.","Today, 10:14 PM"],
 ["warning","Low Solar Generation","Solar output briefly dropped below the preferred charging threshold.","Today, 7:42 PM"],
 ["info","System Update","Monitoring data stream refreshed.","Today, 6:30 PM"],
 ["success","Grid Support","Grid backup returned to standby.","Today, 5:18 PM"],
 ["error","Connection Retry","Temporary sensor connection retry completed.","Yesterday, 11:06 PM"]
];
const developerImages=[
 "data:image/jpeg;base64,",
 "data:image/jpeg;base64,",
 "data:image/jpeg;base64,"
];

const changelog=[
 ["v1.4.0","30 Aug 2026","Monitoring dashboard","Improved live telemetry and responsive layout.","Aryan Dalvi","Completed"],
 ["v1.3.2","27 Aug 2026","EV charging controls","Added charging limit and confirmation controls.","Omkar Gunjal","Completed"],
 ["v1.3.0","22 Aug 2026","Solar analytics","Added daily energy and efficiency charts.","Kartik Gulve","Completed"],
 ["v1.2.0","15 Aug 2026","Weather module","Added weather-to-solar performance view.","Aryan Dalvi","Completed"]
];

function esc(s){return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function showToast(msg){toastEl.textContent=msg;toastEl.style.display="block";clearTimeout(showToast.t);showToast.t=setTimeout(()=>toastEl.style.display="none",2200)}
function badge(text,type="ok"){return `<span class="badge ${type}">${esc(text)}</span>`}
function kpi(icon,label,value,unit="",hint=""){return `<div class="card kpi"><div class="kicon">${icon}</div><div class="label">${label}</div><div class="value">${value}<span class="unit">${unit}</span></div>${hint?`<div class="hint">${hint}</div>`:""}</div>`}
function page(title,sub,body){return `<section class="page ${state.page===title?'active':''}" data-page="${title}">${body}</section>`}

function shell(){
 if(!state.loggedIn){renderLogin();return}
 app.innerHTML=`<div class="app">
  <aside class="sidebar" id="sidebar">
   <div class="brand"><div class="logo">☀</div><div><b>SOLTECH</b><span>Monitoring System</span></div></div>
   <nav class="nav">${navItems.map(([id,ic,label])=>`<button class="${state.page===id?'active':''}" onclick="go('${id}')"><span class="icon">${ic}</span>${label}</button>`).join("")}</nav>
   <div class="side-bottom"><div class="green-note">☀ Green Energy Powered</div><button class="logout" onclick="logout()">↪ Logout</button></div>
  </aside>
  <div class="main">
   <header class="header">
    <div class="header-left"><button class="menu" onclick="toggleSide()">☰</button><div><h1>${titleFor(state.page)}</h1><p>${subtitleFor(state.page)}</p></div></div>
    <div class="header-right"><div class="datetime"><b id="date"></b><span id="time"></span> IST</div>${badge(state.systemPower?"ONLINE":"OFFLINE",state.systemPower?"ok":"danger")}<div class="user"><div class="avatar">♙</div><div><b style="font-size:11px">admin@soltech.com</b><div style="font-size:9px;color:#647080">Administrator</div></div></div></div>
   </header>
   <main class="content">${renderPage()}</main>
  </div>
 </div>`;
 tickClock(); clearInterval(window.clockTimer);window.clockTimer=setInterval(tickClock,1000);
}

function titleFor(p){return ({dashboard:"SOLTECH Monitoring System",realtime:"Real-Time Monitoring",charging:"EV Charging Control",analytics:"Solar Analytics",weather:"Live Weather",history:"Energy History",alerts:"Notifications / Alerts",catalogue:"Project Change Catalogue",developers:"About Developers",settings:"Settings"})[p]}
function subtitleFor(p){return ({dashboard:"Solar Powered EV Charging Station",realtime:"Live sensor telemetry — updates every 3 seconds",charging:"Station 01",analytics:"Energy generation & efficiency trends",weather:"Weather conditions & solar performance estimate",history:"Historical generation & charging records",alerts:"System events and warnings",catalogue:"Version history of all changes made to SOLTECH",developers:"The team behind SOLTECH Monitoring System",settings:"System configuration & critical controls"})[p]}
function tickClock(){let d=new Date();let ds=d.toLocaleDateString("en-IN",{day:"2-digit",month:"long",year:"numeric",timeZone:"Asia/Kolkata"}),ts=d.toLocaleTimeString("en-IN",{hour12:true,timeZone:"Asia/Kolkata"});let a=document.getElementById("date"),b=document.getElementById("time");if(a)a.textContent=ds;if(b)b.textContent=ts}

function renderPage(){
 const p=state.page;
 if(p==="dashboard")return dashboard();
 if(p==="realtime")return realtime();
 if(p==="charging")return charging();
 if(p==="analytics")return analytics();
 if(p==="weather")return weather();
 if(p==="history")return historyPage();
 if(p==="alerts")return alertsPage();
 if(p==="catalogue")return catalogue();
 if(p==="developers")return developers();
 return settings();
}

function dashboard(){
 return `<div class="stack">
  <div>${badge("DEMO / MOCK DATA MODE","mock")}</div>
  <div class="grid g5">
   ${kpi("☀","Solar Power Generated",state.solar.toFixed(1),"kW")}${kpi("ϟ","Current Solar Power",state.solar.toFixed(1),"kW")}
   ${kpi("◉","Today's Energy",state.todayEnergy.toFixed(1),"kWh")}${kpi("⌁","Total Energy Generated",state.totalEnergy.toFixed(1),"kWh")}${kpi("▣","EV Charging Power",state.evPower.toFixed(1),"kW")}
   ${kpi("↗","Energy Used for EV Charging",state.delivered.toFixed(1),"kWh")}${kpi("⌁","Solar Panel Efficiency","82.4","%","Estimated")}
   ${kpi("◉","Charging Station Status",state.charging)}${kpi("▰","EV Battery",state.battery,"%")}${kpi("↓","Grid Power Usage",state.grid?"1.8":"0","kW")}
  </div>
  <div class="grid g3">
   <div class="card pad" style="grid-column:span 2"><h3 class="section-title">Energy Flow</h3>${flowDiagram()}</div>
   <div class="card pad"><h3 class="section-title">☁ Live Weather</h3><div style="font-size:28px;font-weight:750">28°C</div><div style="color:var(--muted);font-size:12px;margin:3px 0 13px">Partly Cloudy</div><div class="grid g2" style="font-size:10px;color:var(--muted)"><span>Humidity: 61%</span><span>Wind: 3.8 m/s</span><span>Cloud: 28%</span><span>UV: 7</span></div><div style="font-size:9px;color:#fbbf24;margin-top:12px">Simulated weather</div></div>
  </div>
  <div class="grid g2">
   <div class="card pad"><h3 class="section-title">System Status</h3><div class="grid g2">${statusRow("System Status",state.systemPower?"ONLINE":"OFFLINE",state.systemPower?"ok":"danger")}${statusRow("Solar Status",state.solar>.1?"GENERATING":"IDLE","ok")}${statusRow("EV Charger",state.charging,"ok")}${statusRow("Monitoring",state.monitoring?"ACTIVE":"STANDBY",state.monitoring?"ok":"warn")}${statusRow("Internet","CONNECTED","ok")}${statusRow("Weather API","CONNECTED","ok")}</div></div>
   <div class="card pad"><h3 class="section-title">Recent Alerts</h3>${alerts.slice(0,4).map(a=>alertRow(a)).join("")}</div>
  </div>
  ${developers(true)}
 </div>`
}
function statusRow(a,b,t){return `<div class="row-status"><span>${a}</span>${badge(b,t)}</div>`}
function flowDiagram(){return `<div class="energy-flow">${node("SOLAR PANELS",state.solar.toFixed(1)+" kW")}${arrow(state.solar>.1)}${node("SOLAR CONTROLLER","")}${arrow(state.solar>.1)}${node("EV CHARGING STATION",state.charging)}${arrow(state.evPower>.1)}${node("EV",state.battery+"%")}${state.grid?`<div style="color:#fbbf24;font-size:10px;margin-top:8px">+ Grid backup active (1.8 kW)</div>`:""}</div>`}
function node(a,b){return `<div class="node"><b>${a}</b><small>${b}</small></div>`}
function arrow(live){return `<div class="arrow ${live?"live":""}">↓</div>`}
function alertRow(a){let t=a[0]==="success"?"ok":a[0]==="warning"?"warn":a[0]==="error"?"danger":"info";return `<div class="alert-item"><div><b>${a[1]}</b><p>${a[2]}</p></div><span class="date">${a[3]}</span></div>`}

function realtime(){
 return `<div class="stack"><div>${badge("MOCK DATA MODE","mock")} ${badge(state.monitoring?"ACTIVE":"STANDBY",state.monitoring?"ok":"warn")}</div>
 <div class="card pad"><h3 class="section-title">Solar Array</h3><div class="grid g4">${kpi("ϟ","Solar Voltage","384","V")}${kpi("ϟ","Solar Current","22.4","A")}${kpi("⌁","Solar Power",state.solar.toFixed(1),"kW")}${kpi("♨","Panel Temperature","42","°C")}</div></div>
 <div class="card pad"><h3 class="section-title">EV Charging</h3><div class="grid g4">${kpi("▣","EV Charging Power",state.evPower.toFixed(1),"kW")}${kpi("ϟ","EV Charging Current","26.1","A")}${kpi("ϟ","EV Charging Voltage","238","V")}${kpi("⌁","Charging Percentage",state.battery,"%")}</div><div class="grid g3" style="margin-top:16px">${kpi("◷","Charging Duration","02:18:42")}${kpi("◷","Est. Remaining Time","01:06:15")}${kpi("♨","Station Temperature","35","°C")}</div></div>
 <div class="card pad"><h3 class="section-title">System Status</h3><div class="tabs">${badge(state.systemPower?"ONLINE":"OFFLINE",state.systemPower?"ok":"danger")}${badge(state.charging,"ok")}${badge(state.mode,"info")}</div></div></div>`
}

function charging(){
 let manual=state.mode==="MANUAL";
 return `<div class="stack"><div class="tabs"><button class="tab ${!manual?"active":""}" onclick="setMode('AUTO')">AUTO MODE</button><button class="tab ${manual?"active":""}" onclick="setMode('MANUAL')">MANUAL MODE</button></div>
 ${!manual?`<div class="card pad"><h3 class="section-title">${badge("AUTO MODE ACTIVE","ok")}</h3><div class="grid g3">${kpi("ϟ","Solar Power Available",state.solar.toFixed(1),"kW")}${kpi("▣","EV Charging",state.evPower.toFixed(1),"kW")}${kpi("⌁","Grid Support",state.grid?"ON":"OFF")}</div><p style="font-size:10px;color:var(--muted);margin:16px 0 0">Charging power is automatically managed based on available solar generation to minimize grid usage. Switch to Manual Mode to take direct control.</p></div>`:
 `<div class="card pad stack"><div class="toolbar"><span style="font-size:12px;color:var(--muted)">Vehicle</span>${badge("CONNECTED","ok")}</div>
 <div class="grid g4">${kpi("▣","Battery",state.battery,"%")}${kpi("ϟ","Charging Power",state.evPower.toFixed(1),"kW")}${kpi("ϟ","Charging Voltage","238","V")}${kpi("ϟ","Charging Current","26.1","A")}</div>
 <div class="grid g3">${kpi("◷","Charging Time","02:18:42")}${kpi("⌁","Energy Delivered",state.delivered.toFixed(1),"kWh")}${kpi("◷","Est. Remaining Time","01:06:15")}</div>
 <div class="toolbar"><label style="font-size:10px;color:var(--muted);width:180px">Charging Power Limit (kW)</label><input class="range" type="range" min="1" max="22" step=".5" value="${state.limit}" oninput="state.limit=+this.value;document.getElementById('limitVal').textContent=this.value+' kW'"><b id="limitVal" style="font-size:11px;width:55px;text-align:right">${state.limit} kW</b></div>
 <div class="tabs"><button class="btn green" onclick="chargingAction('START')">▶ START CHARGING</button><button class="btn amber" onclick="chargingAction('PAUSE')">Ⅱ PAUSE CHARGING</button><button class="btn red" onclick="chargingAction('STOP')">■ STOP CHARGING</button></div>
 </div>`}</div>`
}

function setMode(m){state.mode=m;showToast("Mode changed to "+m);shell()}
function chargingAction(a){if(a==="STOP" && !confirm("Stop the EV charging session?"))return;state.charging=a==="START"?"CHARGING":a==="PAUSE"?"PAUSED":"STOPPED";if(a==="START")state.evPower=6.2;if(a==="STOP")state.evPower=0;showToast("Charging status: "+state.charging);shell()}

function svgChart(){
 let pts=[8,10,7,13,11,15,12,17,14,18,16,20], max=22;
 const poly=pts.map((v,i)=>`${40+i*65},${245-v/max*195}`).join(" ");
 const area=`40,245 ${poly} 755,245`;
 return `<div class="chart"><svg viewBox="0 0 800 270" preserveAspectRatio="none"><line x1="40" y1="245" x2="770" y2="245" stroke="#26313c"/><line x1="40" y1="50" x2="40" y2="245" stroke="#26313c"/><polygon points="${area}" fill="rgba(34,197,94,.10)"/><polyline points="${poly}" fill="none" stroke="#22c55e" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${pts.map((v,i)=>`<circle cx="${40+i*65}" cy="${245-v/max*195}" r="3" fill="#22c55e"/>`).join("")}<text x="45" y="263" fill="#657181" font-size="10">06:00</text><text x="350" y="263" fill="#657181" font-size="10">12:00</text><text x="680" y="263" fill="#657181" font-size="10">18:00</text></svg></div>`
}
function analytics(){
 return `<div class="stack"><div class="tabs">${["live","today","7days","30days"].map(x=>`<button class="tab ${x==="live"?"active":""}" onclick="showToast('${x.toUpperCase()} selected')">${x.toUpperCase().replace("7DAYS","7 DAYS").replace("30DAYS","30 DAYS")}</button>`).join("")}</div>
 <div class="card pad"><h3 class="section-title">Time vs Solar Power (kW)</h3><div class="legend"><span><i class="dot" style="background:#22c55e"></i>Solar</span><span><i class="dot" style="background:#38bdf8"></i>EV Charging</span><span><i class="dot" style="background:#f59e0b"></i>Grid</span></div>${svgChart()}</div>
 <div class="card pad"><h3 class="section-title">Solar Panel Efficiency Trend</h3>${svgChart()}<p style="font-size:9px;color:#647080">Efficiency values are estimated based on simulated irradiance and temperature.</p></div></div>`
}
function weather(){
 return `<div class="stack"><div>${badge("SIMULATED WEATHER — configure WEATHER_API_KEY for live data","mock")}</div>
 <div class="grid g4">${kpi("♨","Temperature","28","°C")}${kpi("☁","Weather Condition","Partly Cloudy")}${kpi("◌","Humidity","61","%")}${kpi("≋","Wind Speed","3.8","m/s")}${kpi("☁","Cloud Cover","28","%")}${kpi("☀","UV Index","7")}${kpi("↑","Sunrise","06:12 AM")}${kpi("↓","Sunset","06:58 PM")}</div>
 <div class="card pad"><h3 class="section-title">Weather ↔ Solar Performance</h3><div class="grid g5">${kpi("☁","Weather","Partly Cloudy")}${kpi("♨","Temperature","28","°C")}${kpi("☁","Cloud Cover","28","%")}${kpi("☀","Solar Generation",state.solar.toFixed(1),"kW")}${kpi("⌁","Panel Efficiency","82.4","%","Estimated")}</div><p style="font-size:10px;color:var(--muted)">Solar efficiency may vary depending on sunlight intensity, temperature, cloud cover and environmental conditions.</p></div></div>`
}
function historyPage(){
 return `<div class="stack"><div class="toolbar"><div class="tabs">${["Today","Yesterday","Last 7 Days","Last 30 Days"].map((x,i)=>`<button class="tab ${i===3?"active":""}" onclick="showToast('${x} selected')">${x}</button>`).join("")}</div><button class="btn" onclick="exportCSV()">⇩ Export CSV</button></div>
 <div class="card table-wrap"><table class="table"><thead><tr><th>Date</th><th>Solar (kWh)</th><th>EV Charging</th><th>Grid</th><th>Efficiency</th><th>Duration</th><th>Status</th></tr></thead><tbody>${history.map(r=>`<tr>${r.map((c,i)=>`<td class="${i===6?'':''}">${i===6?badge(c,"ok"):esc(c)}${i===1||i===2||i===3?" kWh":""}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`
}
function exportCSV(){let csv="Date,Solar kWh,EV Charging kWh,Grid kWh,Efficiency,Charging Duration,Status\n"+history.map(r=>r.join(",")).join("\n");let a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="soltech-history.csv";a.click();showToast("CSV exported")}
function alertsPage(){return `<div class="card pad">${alerts.map(a=>alertRow(a)).join("")}</div>`}
function catalogue(){
 return `<div class="stack"><div class="toolbar"><span style="font-size:11px;color:var(--muted)">Version history of all changes made to SOLTECH</span><button class="btn green" onclick="addChange()">＋ Add Entry</button></div>
 <div class="card table-wrap"><table class="table"><thead><tr><th>Version</th><th>Date</th><th>Feature / Change</th><th>Description</th><th>Developer</th><th>Status</th></tr></thead><tbody>${changelog.map(r=>`<tr>${r.map((c,i)=>`<td>${i===5?badge(c,"ok"):esc(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`
}
function addChange(){let v=prompt("Version","v1.5.0");if(!v)return;let f=prompt("Feature / Change","New improvement");if(!f)return;changelog.unshift([v,new Date().toLocaleDateString("en-IN"),f,"Added from the simplified standalone version.","Admin","Completed"]);showToast("Catalogue entry added");shell()}
function developers(compact=false){
 let cards=[["Mr. Aryan Dalvi","Project Owner / Lead Developer","AD","+91 7249738125","soltech238@gmail.com"],["Mr. Omkar Gunjal","Developer","OG","+91 9284498093",""],["Mr. Kartik Gulve","Developer","KG","+91 7972742175",""]];
 return compact?`<div class="card pad"><h3 class="section-title" style="text-align:center">SOLTECH MONITORING SYSTEM</h3><p style="text-align:center;color:var(--muted);font-size:10px;margin-top:-8px">Developed by</p>${cards.map((d,i)=>devCard(d,i===1,i)).join("")}</div>`:
 `<div class="stack"><div class="card pad" style="text-align:center"><h2 style="font-size:20px;margin:0 0 4px">SOLTECH MONITORING SYSTEM</h2><p style="font-size:11px;color:var(--muted)">Developed by</p></div><div style="max-width:760px;margin:auto">${cards.map((d,i)=>devCard(d,i===1,i)).join("")}</div></div>`
}
function devCard(d,rev,i=0){return `<div class="card developer ${rev?"reverse":""}"><div class="dev-photo"><img src="${developerImages[i]}" alt="${esc(d[0])}"></div><div class="dev-info"><h3>${d[0]}</h3><p>${d[1]}</p><p>${d[3]}${d[4]?" · "+d[4]:""}</p></div></div>`}
function settings(){
 return `<div class="stack">
  <div class="card pad setting"><div><h3>Real-Time Monitoring</h3><p>Live sensor polling and dashboard updates</p>${!state.monitoring?`<p style="color:#fbbf24">Real-time monitoring has been disabled. Historical data remains available.</p>`:""}</div>${toggle("monitoring",state.monitoring)}</div>
  <div class="card pad setting"><div><h3>Grid Backup Support</h3><p>Allow grid power to supplement EV charging when solar is low</p></div>${toggle("grid",state.grid)}</div>
  <div class="card pad" style="border-color:rgba(239,68,68,.2)"><div class="setting"><div><h3>System Power</h3><p>Turning this OFF stops charging and takes the station offline</p></div>${toggle("systemPower",state.systemPower)}</div><div class="tabs" style="margin-top:16px">${badge(state.systemPower?"ONLINE":"OFFLINE",state.systemPower?"ok":"danger")}${badge(state.charging,"ok")}${badge(state.monitoring?"ACTIVE":"STANDBY",state.monitoring?"ok":"warn")}</div></div>
 </div>`
}
function toggle(key,val){return `<button class="toggle ${val?"on":""}" onclick="toggleSetting('${key}')"><i></i></button>`}
function toggleSetting(k){if(k==="systemPower"&&!state.systemPower===false){} if(k==="systemPower"&&!state.systemPower){state.systemPower=true}else if(k==="systemPower"){if(!confirm("Turn OFF the charging station? This will stop charging and take the system offline."))return;state.systemPower=false;state.charging="STOPPED";state.evPower=0}else state[k]=!state[k];showToast(k+" updated");shell()}

function renderLogin(){
 app.innerHTML=`<div class="login"><div class="card login-card"><div class="logo login-logo">☀</div><h1>SOLTECH MONITORING SYSTEM</h1><div class="login-sub">☀ Solar Powered EV Charging Station</div>
 <form onsubmit="login(event)"><div class="field"><label>Email / Username</label><input id="email" type="email" required placeholder="admin@soltech.com"></div><div class="field"><label>Password</label><input id="password" type="password" required placeholder="••••••••"></div><div id="loginError"></div><button class="login-btn">LOGIN</button></form><div class="login-note">Standalone demo mode. Any valid email/password will open the dashboard.</div></div></div>`
}
function login(e){e.preventDefault();state.loggedIn=true;localStorage.setItem("soltech_demo_login","1");state.page="dashboard";shell()}
function logout(){state.loggedIn=false;localStorage.removeItem("soltech_demo_login");shell()}
function toggleSide(){document.getElementById("sidebar")?.classList.toggle("open")}
function go(p){state.page=p;document.getElementById("sidebar")?.classList.remove("open");shell()}

shell();
